CREATE TABLE IF NOT EXISTS farm_profile (id VARCHAR(36) PRIMARY KEY, owner_name VARCHAR(255) NOT NULL, phone_number VARCHAR(20) NOT NULL, secondary_contact_phone VARCHAR(20), survey_number VARCHAR(100), village VARCHAR(100), taluk VARCHAR(100), district VARCHAR(100), total_area FLOAT, cultivable_area FLOAT, irrigation_classification VARCHAR(50), detected_soil_type VARCHAR(50), soil_calibration_m FLOAT, soil_calibration_c FLOAT, verification_status VARCHAR(20), verification_method VARCHAR(20), verified_at TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS fields (id VARCHAR(36) PRIMARY KEY, farm_id VARCHAR(36) NOT NULL REFERENCES farm_profile(id), name VARCHAR(100) NOT NULL, crop_type VARCHAR(50) NOT NULL, growth_stage VARCHAR(50) NOT NULL, dimensions_length FLOAT, dimensions_width FLOAT, gps_coordinates JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS threshold_profiles (id SERIAL PRIMARY KEY, crop_type VARCHAR(50) NOT NULL, growth_stage VARCHAR(50) NOT NULL, moisture_min FLOAT, moisture_max FLOAT, ph_min FLOAT, ph_max FLOAT, n_min FLOAT, p_min FLOAT, k_min FLOAT, temp_min FLOAT, temp_max FLOAT, humidity_min FLOAT, humidity_max FLOAT, UNIQUE(crop_type, growth_stage));
CREATE TABLE IF NOT EXISTS sensor_readings (id BIGSERIAL PRIMARY KEY, field_id VARCHAR(36) NOT NULL REFERENCES fields(id), timestamp TIMESTAMP NOT NULL, soil_moisture FLOAT NOT NULL, ph FLOAT NOT NULL, raw_n FLOAT, raw_p FLOAT, raw_k FLOAT, calibrated_n FLOAT, calibrated_p FLOAT, calibrated_k FLOAT, temperature FLOAT, humidity FLOAT, node_battery_voltage FLOAT, is_backlogged BOOLEAN DEFAULT FALSE, received_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(field_id, timestamp));
CREATE TABLE IF NOT EXISTS flagged_readings (id BIGSERIAL PRIMARY KEY, field_id VARCHAR(36) NOT NULL REFERENCES fields(id), timestamp TIMESTAMP NOT NULL, raw_payload JSON NOT NULL, reason VARCHAR(100) NOT NULL, threshold_value FLOAT, actual_value FLOAT, is_disputed BOOLEAN DEFAULT FALSE, dispute_notes TEXT, received_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS action_logs (id VARCHAR(36) PRIMARY KEY, field_id VARCHAR(36) NOT NULL REFERENCES fields(id), action_type VARCHAR(20) NOT NULL, timestamp TIMESTAMP NOT NULL, details TEXT, fertilizer_kg_per_ha FLOAT, is_disputed BOOLEAN DEFAULT FALSE, dispute_reason TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS alerts (id VARCHAR(36) PRIMARY KEY, field_id VARCHAR(36) NOT NULL REFERENCES fields(id), reading_id BIGINT REFERENCES sensor_readings(id), alert_type VARCHAR(50) NOT NULL, status VARCHAR(20) DEFAULT 'active', escalation_level INTEGER DEFAULT 0, notified_at TIMESTAMP, acknowledged_at TIMESTAMP, escalated_at TIMESTAMP, compliance_notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS environmental_events (id VARCHAR(36) PRIMARY KEY, farm_id VARCHAR(36) NOT NULL REFERENCES farm_profile(id), source_field_id VARCHAR(36), event_type VARCHAR(50) NOT NULL, raw_value TEXT, timestamp TIMESTAMP NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS crop_cycle_history (id VARCHAR(36) PRIMARY KEY, field_id VARCHAR(36) NOT NULL REFERENCES fields(id), crop_grown VARCHAR(50) NOT NULL, season VARCHAR(20) NOT NULL, start_date DATE NOT NULL, end_date DATE, n_applied_kg_ha FLOAT, p_applied_kg_ha FLOAT, k_applied_kg_ha FLOAT, yield_achieved_kg_ha FLOAT, expert_label VARCHAR(50), within_compliance BOOLEAN, notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS weather_snapshots (id BIGSERIAL PRIMARY KEY, field_id VARCHAR(36) NOT NULL REFERENCES fields(id), fetched_at TIMESTAMP NOT NULL, forecast_time TIMESTAMP NOT NULL, temperature_c FLOAT, humidity_pct FLOAT, rainfall_mm FLOAT, rain_probability FLOAT, wind_speed_kmh FLOAT, description TEXT, UNIQUE(field_id, forecast_time));
CREATE TABLE IF NOT EXISTS verification_audit_log (id BIGSERIAL PRIMARY KEY, farm_id VARCHAR(36) NOT NULL REFERENCES farm_profile(id), action VARCHAR(50) NOT NULL, field_changed VARCHAR(100), old_value TEXT, new_value TEXT, actor VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_preferences (id VARCHAR(36) PRIMARY KEY, farm_id VARCHAR(36), preferred_language VARCHAR(5) DEFAULT 'en', preferred_area_unit VARCHAR(20) DEFAULT 'hectare', voice_playback_enabled BOOLEAN DEFAULT TRUE, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_sensor_readings_field_time ON sensor_readings(field_id, timestamp DESC);
CREATE INDEX IF NOT EXISTS idx_alerts_field_status ON alerts(field_id, status);
CREATE TABLE IF NOT EXISTS auth_users (id VARCHAR(36) PRIMARY KEY, email VARCHAR(320) NOT NULL UNIQUE, password_hash VARCHAR(512) NOT NULL, is_email_verified BOOLEAN NOT NULL DEFAULT FALSE, is_disabled BOOLEAN NOT NULL DEFAULT FALSE, farm_id VARCHAR(36) REFERENCES farm_profile(id), email_verification_token_hash VARCHAR(64) UNIQUE, email_verification_expires_at TIMESTAMP, password_reset_token_hash VARCHAR(64) UNIQUE, password_reset_expires_at TIMESTAMP, session_version INTEGER NOT NULL DEFAULT 0, last_login_at TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS auth_sessions (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL REFERENCES auth_users(id) ON DELETE CASCADE, token_hash VARCHAR(64) NOT NULL UNIQUE, session_version INTEGER NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, last_seen_at TIMESTAMP NOT NULL, expires_at TIMESTAMP NOT NULL, revoked_at TIMESTAMP, ip_address VARCHAR(64));
CREATE INDEX IF NOT EXISTS idx_auth_sessions_user ON auth_sessions(user_id);
CREATE INDEX IF NOT EXISTS idx_auth_sessions_token ON auth_sessions(token_hash);
